def decide(recipient_reputation, round_num, my_history):
    # Compute own cooperation streak (consecutive cooperations at end)
    streak = 0
    for action in reversed(my_history):
        if action:  # cooperate
            streak += 1
        else:
            break

    # Base threshold: start cooperative, increase with round, become more generous with longer streak
    threshold = 0.0 - 0.2 * streak + 0.02 * round_num
    if streak >= 5:
        threshold -= 0.1  # extra generosity for long cooperative streaks
    return recipient_reputation > threshold

